# Generated by Selenium IDE / Pytest for SGCS Project
import pytest
import time
from selenium import webdriver
from selenium.webdriver.common.by import By
from selenium.webdriver.support.ui import WebDriverWait
from selenium.webdriver.support import expected_conditions as EC

class TestSubmitComplaint:
    def setup_method(self, method):
        # Configure Chrome WebDriver
        options = webdriver.ChromeOptions()
        options.add_argument("--start-maximized")
        self.driver = webdriver.Chrome(options=options)
        self.wait = WebDriverWait(self.driver, 10)  # Explicit wait

    def teardown_method(self, method):
        self.driver.quit()

    def set_react_input(self, element, value):
        self.driver.execute_script("""
            const el = arguments[0];
            const val = arguments[1];
            const desc = Object.getOwnPropertyDescriptor(
                el.tagName === 'TEXTAREA' ? window.HTMLTextAreaElement.prototype : window.HTMLInputElement.prototype,
                'value'
            );
            desc.set.call(el, val);
            el.dispatchEvent(new Event('input', { bubbles: true }));
            el.dispatchEvent(new Event('change', { bubbles: true }));
        """, element, value)

    def test_submit_complaint(self):
        # Step 1: Login as Citizen
        self.driver.get("http://localhost:5173/login")
        
        email_field = self.wait.until(
            EC.visibility_of_element_located((By.ID, "login-email-input"))
        )
        email_field.clear()
        email_field.send_keys("citizen@example.com")

        password_field = self.wait.until(
            EC.visibility_of_element_located((By.ID, "login-password-input"))
        )
        password_field.clear()
        password_field.send_keys("Citizen@123")

        login_btn = self.wait.until(
            EC.element_to_be_clickable((By.CSS_SELECTOR, "button[type='submit']"))
        )
        login_btn.click()

        # Step 2: Navigate to Submit Complaint Form via Dashboard button
        self.wait.until(EC.url_contains("/citizen/dashboard"))
        report_btn = self.wait.until(
            EC.presence_of_element_located((By.XPATH, "//button[contains(., 'Report New Issue')]"))
        )
        self.driver.execute_script("arguments[0].click();", report_btn)
        self.wait.until(EC.url_contains("/citizen/complaints/submit"))

        # Step 3: Enter Complaint Title
        title_field = self.wait.until(
            EC.visibility_of_element_located((By.ID, "complaint-title-input"))
        )
        self.set_react_input(title_field, "Test Pothole on Main Road")

        # Step 4: Enter Grievance Description
        desc_field = self.wait.until(
            EC.visibility_of_element_located((By.ID, "complaint-description-input"))
        )
        self.set_react_input(desc_field, "Deep pothole near the central junction causing traffic slowdown.")

        # Step 5: Enter Specific Location
        loc_field = self.wait.until(
            EC.visibility_of_element_located((By.ID, "complaint-location-input"))
        )
        self.set_react_input(loc_field, "Opposite City Hospital Gate, MG Road")

        # Step 6: Click Submit Grievance button
        submit_btn = self.wait.until(
            EC.element_to_be_clickable((By.ID, "complaint-submit-btn"))
        )
        self.driver.execute_script("arguments[0].click();", submit_btn)

        # Step 7: Verify Grievance Registered Successfully confirmation view
        success_title = self.wait.until(
            EC.visibility_of_element_located((By.XPATH, "//*[contains(text(), 'Grievance Registered Successfully')]"))
        )
        assert success_title.is_displayed(), "Complaint registration banner not displayed!"
        
        # Verify Tracking Reference Number is generated
        ref_header = self.wait.until(
            EC.visibility_of_element_located((By.XPATH, "//*[contains(text(), 'COMPLAINT REFERENCE NUMBER')]"))
        )
        assert ref_header.is_displayed(), "Reference tracking number missing!"
        time.sleep(3)

if __name__ == "__main__":
    pytest.main(["-v", __file__])
